/**
 * Seed script: Expand 7 Course Modules with 5 additional lessons each
 * Run: node seed-expanded-lessons-v2.mjs
 * 
 * Parses lesson files generated by parallel content generation and inserts into database.
 */
import 'dotenv/config';
import mysql from 'mysql2/promise';
import fs from 'fs';

const DATABASE_URL = process.env.DATABASE_URL;
if (!DATABASE_URL) {
  console.error('DATABASE_URL not set');
  process.exit(1);
}

const connection = await mysql.createConnection(DATABASE_URL);

// Module slug -> lesson file path mapping
const MODULE_FILES = {
  'industrial-networking': '/home/ubuntu/lessons_file/0_ce4nbML0F8ZNDIsbe6An6S_1778886451116_na1fn_L2hvbWUvdWJ1bnR1L2xlc3NvbnM.txt',
  'sensors-instrumentation': '/home/ubuntu/lessons_file/1_R3IFtbodI6SkXR6aKJssNo_1778886354161_na1fn_L2hvbWUvdWJ1bnR1L3NlbnNvcnMtaW5zdHJ1bWVudGF0aW9uLWxlc3NvbnM.txt',
  'robotics-fundamentals': '/home/ubuntu/lessons_file/2_8bT2oiGJjvF3GokATIXl5j_1778886360890_na1fn_L2hvbWUvdWJ1bnR1L3JvYm90aWNzX2xlc3NvbnM.txt',
  'print-reading': '/home/ubuntu/lessons_file/3_LkfLNm2m0rCmfFwVyZAo1a_1778886477785_na1fn_L2hvbWUvdWJ1bnR1L3ByaW50LXJlYWRpbmctZWxlY3RyaWNhbC1sZXNzb25z.txt',
  'safety-systems': '/home/ubuntu/lessons_file/4_JAu12yNUwiYOXpGrgiN00N_1778886369514_na1fn_L2hvbWUvdWJ1bnR1L3NhZmV0eS1zeXN0ZW1zLWxlc3NvbnM.txt',
  'process-control': '/home/ubuntu/lessons_file/5_QZ3ShUPSG2ubuCk7vS9XwC_1778886402237_na1fn_L2hvbWUvdWJ1bnR1L3Byb2Nlc3NfY29udHJvbF9sZXNzb25z.txt',
  'power-distribution': '/home/ubuntu/lessons_file/6_JZTEsylhwMvFf8WZy2AQM0_1778886387324_na1fn_L2hvbWUvdWJ1bnR1L2xlc3NvbnM.txt',
};

function parseLessonFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const lessons = [];
  const blocks = content.split('===LESSON_START===').filter(b => b.trim());
  
  for (const block of blocks) {
    const endIdx = block.indexOf('===LESSON_END===');
    const lessonText = endIdx >= 0 ? block.substring(0, endIdx) : block;
    
    const slugMatch = lessonText.match(/SLUG:\s*(.+)/);
    const titleMatch = lessonText.match(/TITLE:\s*(.+)/);
    const orderMatch = lessonText.match(/ORDER_INDEX:\s*(\d+)/);
    const minutesMatch = lessonText.match(/ESTIMATED_MINUTES:\s*(\d+)/);
    const contentMatch = lessonText.match(/CONTENT:\s*([\s\S]+)/);
    
    if (slugMatch && titleMatch && orderMatch && minutesMatch && contentMatch) {
      lessons.push({
        slug: slugMatch[1].trim(),
        title: titleMatch[1].trim(),
        orderIndex: parseInt(orderMatch[1].trim()),
        estimatedMinutes: parseInt(minutesMatch[1].trim()),
        content: contentMatch[1].trim(),
      });
    }
  }
  
  return lessons;
}

async function seedLessons(moduleSlug, lessons) {
  const [rows] = await connection.query(
    'SELECT id FROM course_modules WHERE slug = ?', [moduleSlug]
  );
  
  if (rows.length === 0) {
    console.error(`  Module not found: ${moduleSlug}`);
    return 0;
  }
  
  const moduleId = rows[0].id;
  let inserted = 0;
  
  for (const lesson of lessons) {
    const [existing] = await connection.query(
      'SELECT id FROM course_lessons WHERE moduleId = ? AND slug = ?',
      [moduleId, lesson.slug]
    );
    
    if (existing.length > 0) {
      await connection.query(
        'UPDATE course_lessons SET title = ?, orderIndex = ?, content = ?, estimatedMinutes = ?, isPublished = 1, updatedAt = NOW() WHERE moduleId = ? AND slug = ?',
        [lesson.title, lesson.orderIndex, lesson.content, lesson.estimatedMinutes, moduleId, lesson.slug]
      );
      console.log(`    Updated: ${lesson.slug}`);
    } else {
      await connection.query(
        'INSERT INTO course_lessons (moduleId, slug, title, orderIndex, content, estimatedMinutes, isPublished) VALUES (?, ?, ?, ?, ?, ?, 1)',
        [moduleId, lesson.slug, lesson.title, lesson.orderIndex, lesson.content, lesson.estimatedMinutes]
      );
      console.log(`    Inserted: ${lesson.slug}`);
      inserted++;
    }
  }
  
  // Update totalLessons count
  const [countResult] = await connection.query(
    'SELECT COUNT(*) as cnt FROM course_lessons WHERE moduleId = ? AND isPublished = 1', [moduleId]
  );
  await connection.query('UPDATE course_modules SET totalLessons = ? WHERE id = ?', [countResult[0].cnt, moduleId]);
  console.log(`    Module totalLessons updated to ${countResult[0].cnt}`);
  
  return inserted;
}

try {
  console.log('=== Expanding 7 Course Modules with Additional Lessons ===\n');
  
  let totalInserted = 0;
  
  for (const [moduleSlug, filePath] of Object.entries(MODULE_FILES)) {
    console.log(`\nProcessing: ${moduleSlug}...`);
    
    if (!fs.existsSync(filePath)) {
      console.error(`  File not found: ${filePath}`);
      continue;
    }
    
    const lessons = parseLessonFile(filePath);
    console.log(`  Parsed ${lessons.length} lessons`);
    
    if (lessons.length === 0) {
      console.error(`  No lessons parsed from file!`);
      continue;
    }
    
    const inserted = await seedLessons(moduleSlug, lessons);
    totalInserted += inserted;
  }
  
  console.log(`\n=== Done! Inserted ${totalInserted} new lessons across 7 modules ===`);
} catch (error) {
  console.error('Error seeding lessons:', error);
} finally {
  await connection.end();
}
